<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
class JobSeekerDashboardController extends Controller { public function index(Request $r){$apps=$r->user()->applications()->with('job')->latest()->get();$stats=['applications'=>$apps->count(),'pending'=>$apps->where('status','pending')->count(),'shortlisted'=>$apps->where('status','shortlisted')->count(),'hired'=>$apps->where('status','hired')->count()];$recentApplications=$apps->take(5);return view('job-seeker.dashboard',compact('stats','recentApplications'));}}
class EmployerDashboardController extends Controller { public function index(Request $r){$u=$r->user();$jobs=$u->jobs()->with('applications')->latest()->get();$stats=['jobs'=>$jobs->count(),'active'=>$jobs->where('status','published')->count(),'applications'=>$jobs->sum(fn($j)=>$j->applications->count()),'hired'=>$jobs->sum(fn($j)=>$j->applications->where('status','hired')->count())];$recentJobs=$jobs->take(5);return view('employer.dashboard',compact('stats','recentJobs'));}}
class AdminDashboardController extends Controller { public function index(){ $stats=['users'=>\App\Models\User::count(),'employers'=>\App\Models\User::where('role','employer')->count(),'job_seekers'=>\App\Models\User::where('role','job_seeker')->count(),'jobs'=>\App\Models\Job::count(),'applications'=>\App\Models\Application::count()]; return view('admin.dashboard',compact('stats'));}}
